            ResolveIndexedResourceHandle(&core->resources[1].handle, 0x338);
            core->resources[1].x = 0x800000;
            reset_pending = false;
            sound_state = 0;
            right_state = left_state = 2;
            core->unk_6C6C = 9;
            core->resources[8].y = 0;
            core->sprite_matrix.pa = 0x100;
            core->sprite_matrix.pd = 0x100;
